<table><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Origin</td><td>San Ignacio, Chalatenango, El Salvador</td></tr><tr><td>Farm</td><td>Santa Rosa (Lot 244)</td></tr><tr><td>Owner</td><td>Jorge Raúl Rivera</td></tr><tr><td>Altitude</td><td>1,700m</td></tr><tr><td>Variety</td><td>Pacamara</td></tr><tr><td>Process</td><td>Honey</td></tr><tr><td>Roast</td><td>Light</td></tr></tbody></table>
